using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capability using the Brave Search API.
/// Falls back to a simulated search when no API key is configured.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _apiKey;

    public WebSearchTool(HttpClient httpClient, string? braveApiKey)
    {
        _httpClient = httpClient;
        _apiKey = braveApiKey;
    }

    [Description("Searches the web for information on a given query and returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        if (!string.IsNullOrWhiteSpace(_apiKey))
        {
            return await SearchWithBraveAsync(query, maxResults);
        }

        return SimulateSearch(query, maxResults);
    }

    private async Task<string> SearchWithBraveAsync(string query, int maxResults)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}");
        request.Headers.Add("X-Subscription-Token", _apiKey);
        request.Headers.Add("Accept", "application/json");

        var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
        var results = new List<object>();

        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var webResults))
        {
            foreach (var item in webResults.EnumerateArray().Take(maxResults))
            {
                results.Add(new
                {
                    title = item.GetProperty("title").GetString(),
                    url = item.GetProperty("url").GetString(),
                    snippet = item.TryGetProperty("description", out var desc)
                        ? desc.GetString() : ""
                });
            }
        }

        return results.Count > 0
            ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
            : "No results found.";
    }

    private static string SimulateSearch(string query, int maxResults)
    {
        var results = new List<object>
        {
            new { title = $"Overview of {query}", url = $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}", snippet = $"A comprehensive overview covering the key aspects of {query}, including history, current state, and future directions." },
            new { title = $"Latest developments in {query}", url = $"https://news.example.com/{Uri.EscapeDataString(query)}", snippet = $"Recent advances and breakthroughs related to {query} that are shaping the field." },
            new { title = $"{query} - A practical guide", url = $"https://guide.example.com/{Uri.EscapeDataString(query)}", snippet = $"Step-by-step practical guide covering fundamental and advanced concepts of {query}." },
            new { title = $"Research papers on {query}", url = $"https://scholar.example.com/{Uri.EscapeDataString(query)}", snippet = $"Collection of peer-reviewed research papers and studies on {query}." },
            new { title = $"Industry analysis: {query}", url = $"https://analysis.example.com/{Uri.EscapeDataString(query)}", snippet = $"Expert industry analysis examining trends, challenges, and opportunities in {query}." },
        };

        return JsonSerializer.Serialize(results.Take(maxResults), new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capability for the research agent to organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes.AsReadOnly();

    [Description("Saves a research note with a title, content, and source URL. Use this to record key findings during research.")]
    public string AddNote(
        [Description("Short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content,
        [Description("The source URL where this information was found")] string sourceUrl)
    {
        var note = new Note(title, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes with their titles and sources.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}");
            sb.AppendLine($"    Source: {_notes[i].SourceUrl}");
            sb.AppendLine($"    Content: {Truncate(_notes[i].Content, 120)}");
            sb.AppendLine();
        }
        return sb.ToString();
    }

    [Description("Retrieves the full content of a specific note by its number (1-based).")]
    public string GetNote([Description("The note number (1-based index)")] int noteNumber)
    {
        if (noteNumber < 1 || noteNumber > _notes.Count)
            return $"Invalid note number. There are {_notes.Count} notes (1-{_notes.Count}).";

        var note = _notes[noteNumber - 1];
        return $"Title: {note.Title}\nSource: {note.SourceUrl}\nSaved: {note.SavedAt:u}\n\n{note.Content}";
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "...");
}

public sealed record Note(string Title, string Content, string SourceUrl, DateTime SavedAt);

