using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capability for the research agent to organize findings.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    public IReadOnlyList<Note> Notes => _notes.AsReadOnly();

    [Description("Saves a research note with a title, content, and source URL. Use this to record key findings during research.")]
    public string AddNote(
        [Description("Short title summarizing the note")] string title,
        [Description("The detailed content of the note")] string content,
        [Description("The source URL where this information was found")] string sourceUrl)
    {
        var note = new Note(title, content, sourceUrl, DateTime.UtcNow);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved: \"{title}\"";
    }

    [Description("Lists all saved research notes with their titles and sources.")]
    public string ListNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}");
            sb.AppendLine($"    Source: {_notes[i].SourceUrl}");
            sb.AppendLine($"    Content: {Truncate(_notes[i].Content, 120)}");
            sb.AppendLine();
        }
        return sb.ToString();
    }

    [Description("Retrieves the full content of a specific note by its number (1-based).")]
    public string GetNote([Description("The note number (1-based index)")] int noteNumber)
    {
        if (noteNumber < 1 || noteNumber > _notes.Count)
            return $"Invalid note number. There are {_notes.Count} notes (1-{_notes.Count}).";

        var note = _notes[noteNumber - 1];
        return $"Title: {note.Title}\nSource: {note.SourceUrl}\nSaved: {note.SavedAt:u}\n\n{note.Content}";
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "...");
}

public sealed record Note(string Title, string Content, string SourceUrl, DateTime SavedAt);

