using System.ClientModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";
var braveApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY"); // optional

// --- DI setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddHttpClient();

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(new ApiKeyCredential(apiKey))));

var sp = services.BuildServiceProvider();

// --- Tools ---
var httpClient = sp.GetRequiredService<IHttpClientFactory>().CreateClient();
var searchTool = new WebSearchTool(httpClient, braveApiKey);
var noteTool = new NoteTakingTool();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(searchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.AddNote),
    AIFunctionFactory.Create(noteTool.ListNotes),
    AIFunctionFactory.Create(noteTool.GetNote),
};

// --- Agent ---
var chatClient = sp.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(chatClient,
    instructions: """
        You are a research assistant. Your goal is to thoroughly research a topic by:
        1. Searching the web for relevant information using the search tool.
        2. Taking detailed notes on key findings using the note-taking tool.
        3. After gathering sufficient information, list your notes and produce a
           well-structured summary with source citations.

        Always save important findings as notes before writing your summary.
        Include at least 3 distinct search queries to cover the topic broadly.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools",
    tools: tools);

// --- Run ---
Console.WriteLine("🔍 Research Agent");
Console.WriteLine(new string('─', 50));

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync(conversationId: Guid.NewGuid().ToString());

var options = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
});

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary with sources: {topic}",
    session,
    options))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"📝 Total notes taken: {noteTool.Notes.Count}");

foreach (var note in noteTool.Notes)
{
    Console.WriteLine($"   • {note.Title} ({note.SourceUrl})");
}

